const esc = s => String(s).replaceAll("&", "&amp;").replaceAll("<", "&lt;");
export const profilePage = user => `<h1>${esc(user.displayName)}</h1>
<button type="button" data-track="profile.save">Save</button>`;

export const archiveProfile = (db, id, now) => {
  db.prepare("UPDATE profiles SET archived_at = ? WHERE id = ? AND archived_at IS NULL").run(now, id);
  const row = db.prepare("SELECT archived_at FROM profiles WHERE id = ?").get(id);
  return row ? row.archived_at : null;
};


export const activeProfiles = db =>
  db.prepare("SELECT id, name, archived_at FROM profiles WHERE archived_at IS NULL").all();
